374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
387		// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
388		// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
389		// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
390		// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
391		// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
392		// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
393		// 限比较（MaxInterval 已校验为正）。
394		for i := 1; i < len(fd.Trajectory); i++ {
395			prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
396			if cur <= prev {
397				return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
398			}
399			if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
400				return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
401			}
402		}
403		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
404		// 该字段（解码为 nil），数量为 0。
405		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
406			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
407		}
408		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
409		for _, lm := range fd.Landmarks {
410			if lm.ID == "" {
411				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
412			}
413			if _, dup := seenIDs[lm.ID]; dup {
414				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
415			}
416			seenIDs[lm.ID] = struct{}{}
417			if len(lm.Occurrences) == 0 {
418				// 兼容旧布局：平铺字段表示第 1 次出现。
419				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
420					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
421				}
422				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
423					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
424				}
425				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
426					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
427				}
428				continue
429			}
430			activeCount := 0
431			for i, oj := range lm.Occurrences {
432				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
433					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
434				}
435				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
436					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
437				}
438				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
439					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
440				}
441				if oj.Active {
442					activeCount++
443					if i != len(lm.Occurrences)-1 {
444						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
445					}
446				} else if oj.InvalidReason == "" {
447					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
448				}
449				// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
450				// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
451				// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
452				// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
453				// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
454				// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
455				// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
456				// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
457				// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
458				// 观测无关。
459				if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
460					return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
461				}
462				if i > 0 {
463					if !oj.HasFirstSeen {
464						return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
465					}
466					// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
467					if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
468						return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
469					}
470				}
471			}
472			if activeCount > 1 {
473				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
474			}
475		}
476		// 观测重放器：各路标历次出现的时间边界（归属规则见 occurrence.go）
477		// 与逐条重建位置的流程（见 replay.go）和回环校正共享同一实现；来源
478		// 帧的归属核对、次数/首次时间统计、位置核对与校正记录路标列表核对
479		// 都经由它进行。旧文件缺省 sources（解码为 nil）时不构建，这些核对
480		// 都不进行。
481		// tally 是对全部来源帧的唯一一次归属计数扫描（见 tally.go）：路标各
482		// 次出现的总次数核对、首次观测时间核对与各校正记录按结束时间的次数
483		// 核对都从它取数，不再分别重复归属同一批逐帧观测；legacyByKey 是各
484		// 次出现保存的固定旧贡献，两类次数核对都在来源条数上另加它。
485		var (
486			replay      *observationReplay
487			tally       *sourceObservationTally
488			legacyByKey map[occurrenceKey]int
489		)
490		// endSrcIdxs 预登记各校正记录结束帧对应的来源下标 k（对应帧
491		// trajectory[k+1]），只让共享扫描为这些下标保留“截至该帧”的累计快
492		// 照，避免对每一帧都复制整份计数。
493		endSrcIdxs := make(map[int]struct{})
494		if len(fd.Sources) != 0 {
495			replay = newObservationReplay(fd.Config.MergeDistance)
496			for _, lm := range fd.Landmarks {
497				replay.track(lm.ID, occurrenceWindowsOf(lm))
498			}
499			for _, cr := range fd.Corrections {
500				for j := 1; j < len(fd.Trajectory); j++ {
501					if fd.Trajectory[j].Time == cr.EndTime {
502						endSrcIdxs[j-1] = struct{}{}
503						break
504					}
505				}
506			}
507		}
508		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
509		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
510		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
511		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
512		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
513		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
514		if len(fd.Sources) != 0 {
515			// 唯一一次逐帧归属与计数扫描（规则与端点处理见 tally.go）：每条来
516			// 源观测各算一次、同帧重复不去重、空观测帧与 null 旧帧不增长，无
517			// 法归属的观测在此直接拒绝。总次数核对、首次观测时间核对与下方校
518			// 正记录按结束时间的次数核对都读这同一份结果，不再各自重复归属。
519			var err error
520			tally, err = tallySourceObservations(replay, fd.Trajectory, fd.Sources, endSrcIdxs)
521			if err != nil {
522				return err
523			}
524			// 各次出现保存的固定旧观测贡献次数（旧地图缺少逐帧依据的既有观
525			// 测），作为所属出现的既有贡献计入总数；两类次数核对都另加它。
526			legacyByKey = legacyContributions(fd.Landmarks)
527			// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
528			// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
529			// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
530			// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
531			// 次数，正常校正后保存的文件仍满足此不变量。
532			for _, lm := range fd.Landmarks {
533				if len(lm.Occurrences) == 0 {
534					// 旧版平铺路标即第 1 次出现。
535					key := occurrenceKey{id: lm.ID, num: 1}
536					if got := tally.totals[key] + legacyByKey[key]; got != lm.Count {
537						return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
538					}
539					continue
540				}
541				for _, oj := range lm.Occurrences {
542					key := occurrenceKey{id: lm.ID, num: oj.Number}
543					if got := tally.totals[key] + legacyByKey[key]; got != oj.Count {
544						return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
545					}
546				}
547			}
548	
549			// 首次观测时间核对：首次观测时间已知、且全部观测都具有逐帧来源
550			// （无固定旧贡献）的每次出现，记录的首次时间必须准确等于实际归属
551			// 该次出现的最早来源观测帧时间。写早或写晚都是损坏：错误时间即使
552			// 恰好命中某个已保存的帧，只要该帧没有观测这一路标也不能接受；
553			// 错误时间没有对应帧同样拒绝。各次出现分别核对——已失效的旧出现
554			// 与失效后再现的新出现各自依据自己的观测判断，不能互相代替；后续
555			// 帧继续观测或同帧重复观测都不改变首次时间。时间为零或负数是合法
556			// 帧时间，按实际值比较，不把零当作时间未知。旧文件第 1 次出现缺
557			// 少旧观测依据、首次时间未知（HasFirstSeen 为假），或仍含固定旧
558			// 贡献时，其最早观测无从核对，保留旧地图的既有打开规则；但旧路标
559			// 失效后新导入产生的出现依据完整、首次时间已知，不因同一文件存在
560			// 旧历史而跳过核对。回环校正只改位姿与位置，不改观测帧时间，已正
561			// 确保存的校正地图仍满足此不变量。
562			for _, lm := range fd.Landmarks {
563				for _, oj := range lm.Occurrences {
564					if !oj.HasFirstSeen || oj.LegacyCount > 0 {
565						continue
566					}
567					// 次数核对已保证 Count-LegacyCount 条来源观测存在，最早
568					// 帧时间必然已记录；缺失本身即矛盾。
569					key := occurrenceKey{id: lm.ID, num: oj.Number}
570					first, ok := tally.first[key]
571					if !ok || first != oj.FirstSeenTime {
572						return fmt.Errorf("%w: landmark %s occurrence %d records first seen time %d but its earliest sourced observation is at frame time %d", ErrCorrupt, lm.ID, oj.Number, oj.FirstSeenTime, first)
573					}
574				}
575			}
576	
577			// 位置核对：次数相符只说明观测“条数”对得上，还必须核对保存的路标
578			// 位置确实是这些观测依据当前保存位姿重放后的等权平均。每条来源观测
579			// 按所在帧当前保存的位姿转换到地图坐标，按帧时间升序、同帧按输入
580			// 次序，归入各自出现分别重放；同帧对同一标识的多条观测各自参与，
581			// 空观测帧不增加贡献。归组、固定旧贡献起点与逐条重建全部经由与
582			// 回环校正共享的重放器（见 replay.go，单条接纳规则见 aggregate.go），
583			// 旧文件固定旧贡献（LegacyCount 次平均）作为聚合起点——不能当成零，
584			// 也不能用缺少依据的帧数代替。回环校正后保存的文件按当前轨迹重放
585			// 即得到当前位置，不要求等于校正记录里的历史快照；各次出现分别核
586			// 对，已失效的出现同样核对。合并距离只是导入/校正时的接纳门槛，不
587			// 是保存位置偏差的容许范围：重放中出现非有限结果或距离冲突，或最
588			// 终平均位置与保存位置不完全一致，都按损坏拒绝。纯旧文件没有
589			// sources、null 旧帧没有依据，均不重放。
590			for _, lm := range fd.Landmarks {
591				if len(lm.Occurrences) == 0 {
592					// 旧版平铺路标即第 1 次出现。
593					replay.seed(lm.ID, 1, lm.LegacyCount, lm.LegacyMX, lm.LegacyMY)
594					continue
595				}
596				for _, oj := range lm.Occurrences {
597					replay.seed(lm.ID, oj.Number, oj.LegacyCount, oj.LegacyMX, oj.LegacyMY)
598				}
599			}
600			frames := make([]replayFrame, 0, len(fd.Sources))
601			for k, src := range fd.Sources {
602				if src == nil {
603					continue // 旧地图帧：无逐帧依据，其贡献固定在旧贡献起点中
604				}
605				pose := fd.Trajectory[k+1]
606				frames = append(frames, replayFrame{time: pose.Time, pose: pose, observations: src.Observations})
607			}
608			if rej := replay.replay(frames); rej != nil {
609				switch rej.reason {
610				case replayNonFinite:
611					return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d is non-finite", ErrCorrupt, rej.id, rej.num, rej.time)
612				case replayConflict:
613					return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d violates merge distance", ErrCorrupt, rej.id, rej.num, rej.time)
614				default:
615					// 归属（存在性与时间边界）已在上面校验，不会无法归组。
616					return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, rej.id, rej.time)
617				}
618			}
619			checkPosition := func(id string, num int, x, y float64) error {
620				a := replay.agg(id, num)
621				// 次数核对已保证 a.count 与记录次数一致（含旧贡献起点），这里只
622				// 核对位置：保存位置必须与按依据重放出的等权平均完全一致。
623				if a.x != x || a.y != y {
624					return fmt.Errorf("%w: landmark %s occurrence %d is saved at (%v,%v) but its observations replay to (%v,%v)", ErrCorrupt, id, num, x, y, a.x, a.y)
625				}
626				return nil
627			}
628			for _, lm := range fd.Landmarks {
629				if len(lm.Occurrences) == 0 {
630					if err := checkPosition(lm.ID, 1, lm.X, lm.Y); err != nil {
631						return err
632					}
633					continue
634				}
635				for _, oj := range lm.Occurrences {
636					if err := checkPosition(lm.ID, oj.Number, oj.X, oj.Y); err != nil {
637						return err
638					}
639				}
640			}
641		}
642		segIDs := make(map[string]struct{}, len(fd.Segments))
643		for _, sg := range fd.Segments {
644			if sg.ID == "" || sg.Hash == "" {
645				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
646			}
647			if _, dup := segIDs[sg.ID]; dup {
648				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
649			}
650			segIDs[sg.ID] = struct{}{}
651		}
652		corrIDs := make(map[string]struct{}, len(fd.Corrections))
653		// corrRanges 按提交次序记录每条校正覆盖的轨迹下标范围 [anchor,end]
654		// 与范围内逐帧依据是否完整，供下方段首次导入结果核对定位“首次覆盖
655		// 某帧的校正”及其校正前值。
656		type corrRange struct {
657			anchorIdx, endIdx int
658			fullyBased        bool
659		}
660		corrRanges := make([]corrRange, 0, len(fd.Corrections))
661		for _, cr := range fd.Corrections {
662			if cr.ID == "" || cr.Anchor > cr.EndTime {
663				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
664			}
665			// 锚点与结束时间必须准确命中已导入帧：trajectory[0] 是初始位姿，
666			// 不是可校正的帧，也不能用相邻帧的时间代替。轨迹时间已在前面
667			// 校验为严格递增，命中即唯一。
668			anchorIdx, endIdx := -1, -1
669			for j := 1; j < len(fd.Trajectory); j++ {
670				if fd.Trajectory[j].Time == cr.Anchor {
671					anchorIdx = j
672				}
673				if fd.Trajectory[j].Time == cr.EndTime {
674					endIdx = j
675				}
676			}
677			if anchorIdx < 0 || endIdx < 0 {
678				return fmt.Errorf("%w: correction %s range does not hit imported frames", ErrCorrupt, cr.ID)
679			}
680			// 记录必须恰好覆盖 [anchor, end] 内的每一帧：位姿条目数量等于
681			// 范围内帧数，按轨迹时间次序一一对应，且同一份前后位姿的时间
682			// 相同并就是对应帧的时间。缺失、重复、错序、额外加入范围外的
683			// 帧，或把前后时间写成两个不同帧，都使记录不能完整描述声明的
684			// 范围，按损坏拒绝。这里只核对覆盖的帧及时间：快照中的位置、
685			// 朝向和方差是提交时的历史值，不要求等于当前轨迹（后来对相同
686			// 范围再校正、或之后导入新帧，都不影响既有记录的合法性）。
687			if len(cr.Poses) != endIdx-anchorIdx+1 {
688				return fmt.Errorf("%w: correction %s does not cover every frame in its range", ErrCorrupt, cr.ID)
689			}
690			for i, pc := range cr.Poses {
691				ft := fd.Trajectory[anchorIdx+i].Time
692				if pc.Before.Time != ft || pc.After.Time != ft {
693					return fmt.Errorf("%w: correction %s pose entry %d does not match frame time %d", ErrCorrupt, cr.ID, i, ft)
694				}
695				if !finitePose(pc.Before) || !finitePose(pc.After) {
696					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
697				}
698			}
699			// 以下两项核对都只针对范围内逐帧依据完整的校正：范围内任一来源
700			// 帧为 null 旧帧时保留旧文件的既有打开规则，不推测运动方差、也
701			// 不把未知贡献当成零；纯旧文件缺省 sources（长度为 0，重放器不构
702			// 建）时所有记录都不核对。同一文件的其余依据完整的记录不受含旧帧
703			// 记录影响，仍逐一核对。
704			fullyBased := len(fd.Sources) != 0
705			if fullyBased {
706				for k := anchorIdx - 1; k <= endIdx-1; k++ {
707					if fd.Sources[k] == nil {
708						fullyBased = false
709						break
710					}
711				}
712			}
713			corrRanges = append(corrRanges, corrRange{anchorIdx: anchorIdx, endIdx: endIdx, fullyBased: fullyBased})
714			if fullyBased {
715				// 校正后方差核对：锚点帧的校正后方差必须等于该次提交的目标
716				// 方差；其后每帧在目标方差上，按时间顺序累加锚点之后至该帧
717				// 的原运动方差。锚点自身进入该帧的运动方差不再加一次，也不
718				// 能以校正前方差作为起点；累计范围以本记录自己的锚点与结束
719				// 时间为准，后来对重叠范围的再校正与之后追加的帧都不属于本
720				// 记录。目标方差或参与累计的运动方差为负/非有限、累计结果非
721				// 有限，或与保存的校正后方差不完全一致，都按损坏拒绝整份文
722				// 件——每一帧逐一核对，不能只凭锚点与末帧正确就接受中间错误
723				// 的记录；目标方差与运动方差全为零的合法校正同样逐帧通过。
724				accum := cr.Target.Variance
725				if !isFinite(accum) || accum < 0 {
726					return fmt.Errorf("%w: correction %s target variance is negative or non-finite", ErrCorrupt, cr.ID)
727				}
728				for i, pc := range cr.Poses {
729					if i > 0 {
730						// 记录内第 i 帧位于轨迹下标 anchorIdx+i；进入它的运
731						// 动方差在来源 sources[anchorIdx+i-1]（i=1 即锚点之
732						// 后第一帧），锚点自身的来源 sources[anchorIdx-1] 不
733						// 参与累计。
734						mv := fd.Sources[anchorIdx+i-1].MoveVariance
735						if !isFinite(mv) || mv < 0 {
736							return fmt.Errorf("%w: correction %s accumulates negative or non-finite motion variance at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
737						}
738						accum += mv
739						if !isFinite(accum) {
740							return fmt.Errorf("%w: correction %s corrected variance accumulates to non-finite value at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
741						}
742					}
743					if pc.After.Variance != accum {
744						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected variance %v but target variance %v and the motion variances after the anchor accumulate to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Variance, cr.Target.Variance, accum)
745					}
746				}
747				// 几何核对：整条记录必须描述同一次平移和旋转。只核对该记录
748				// 自身保存的校正前后值与目标，不要求历史快照等于当前轨迹——
749				// 后来对重叠范围再校正、或在结束时间之后追加轨迹，都不改写旧
750				// 记录，也不能使原本合法的旧记录被拒绝。重定位规则与 Correct
751				// 提交时共享同一实现（poseShift，见 correction.go）：旋转角、
752				// 余弦正弦与期望位姿的运算次序完全一致，本包写出的合法记录重
753				// 算出的期望值与保存值逐位相同；这里另按容差接纳浮点重算误
754				// 差。锚点的校正后位置必须是目标位置、朝向必须是目标朝向归一
755				// 到 [-π,π) 的结果；其余帧必须与锚点一起做同一次刚体重定
756				// 位：保留校正前相对锚点的位置关系与朝向差。每一帧都逐一核
757				// 对——只有锚点与末帧正确而中间一帧位置偏离或单独转向，同样
758				// 按损坏拒绝；范围只有锚点一帧时本核对即只针对该帧。坐标容差
759				// 为 1e-9 乘以 1、期望值绝对值、保存值绝对值三者的最大值；
760				// 朝向按最短角度差比较，容差 1e-9 弧度。容差与路标合并距离无
761				// 关：合并距离只是导入/校正时的观测接纳门槛，不能用来放过记
762				// 录内部的几何矛盾。目标位置/朝向与锚点校正前完全相同（角度
763				// 等价）时是恒等（只调方差）校正，期望几何直接取校正前值；旋
764				// 转角为零的纯平移校正按各轴平移量逐轴平移——两者都与 Correct
765				// 的同一分支保持一致：横跨 ±1e308 的轨迹上“相对锚点偏移”会
766				// 溢出，不能因此把校正后坐标实际有限的合法校正误判为损坏。
767				anchorBefore := cr.Poses[0].Before
768				shift := newPoseShift(cr.Target, anchorBefore)
769				for i, pc := range cr.Poses {
770					var wantX, wantY, wantHeading float64
771					if i == 0 {
772						wantX, wantY, wantHeading = shift.x, shift.y, shift.heading
773					} else {
774						wantX, wantY, wantHeading = shift.apply(pc.Before)
775					}
776					if !coordClose(pc.After.X, wantX) {
777						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected x %v but the record's target and pre-correction poses rigidly move it to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.X, wantX)
778					}
779					if !coordClose(pc.After.Y, wantY) {
780						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected y %v but the record's target and pre-correction poses rigidly move it to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Y, wantY)
781					}
782					if !angleClose(pc.After.Heading, wantHeading) {
783						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected heading %v but the record's rotation makes it %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Heading, wantHeading)
784					}
785				}
786			}
787			for _, lc := range cr.Landmarks {
788				if lc.ID == "" {
789					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
790				}
791				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
792					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
793					lc.Before.Count < 1 || lc.After.Count < 1 {
794					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
795				}
796			}
797			// 路标列表必须恰好描述记录范围（锚点帧到结束帧，两端包含；之后
798			// 追加的帧不属于范围）内逐帧观测实际涉及的路标出现：范围内被观测
799			// 到的每个（路标，出现编号）必须恰好有一条前后记录，同一次出现被
800			// 多帧或同帧多条观测涉及也只记一条；少记、多记、重复、或把出现
801			// 编号改指该范围没有涉及的另一出现，都按损坏拒绝整份文件，而不是
802			// 只看条目里的坐标与次数是否合法。归组沿用与回环校正相同的时间边
803			// 界规则（重放器，见 replay.go）：同一标识失效后再现属于不同出现，
804			// 即使位置相同也分别对应；已失效的旧出现只要范围内（含失效时刻）
805			// 有它的观测就必须在列表中，不因当前区域查询不再返回它而被排除；
806			// 范围外帧（如记录之后才再现的新出现）的观测不计入。范围内没有
807			// 任何路标观测时列表必须为空，非空即损坏。仅对范围内逐帧依据完整
808			// 的校正做此核对：范围内含 null 旧帧的校正缺少逐帧依据，保留旧地
809			// 图的既有打开规则，不凭推测要求补造观测。
810			if replay != nil && fullyBased {
811				rangeFrames := make([]replayFrame, 0, endIdx-anchorIdx+1)
812				for j := anchorIdx; j <= endIdx; j++ {
813					rangeFrames = append(rangeFrames, replayFrame{time: fd.Trajectory[j].Time, observations: fd.Sources[j-1].Observations})
814				}
815				want := replay.observed(rangeFrames)
816				got := make(map[occurrenceKey]struct{}, len(cr.Landmarks))
817				for _, lc := range cr.Landmarks {
818					num := lc.Occurrence
819					if num == 0 {
820						num = 1 // 更早版本写出的校正记录不带编号，按第 1 次出现解释
821					}
822					if num < 1 || num > replay.occurrences(lc.ID) {
823						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d not touched by its range", ErrCorrupt, cr.ID, lc.ID, num)
824					}
825					key := occurrenceKey{id: lc.ID, num: num}
826					if _, dup := got[key]; dup {
827						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d more than once", ErrCorrupt, cr.ID, lc.ID, num)
828					}
829					got[key] = struct{}{}
830				}
831				for key := range want {
832					if _, ok := got[key]; !ok {
833						return fmt.Errorf("%w: correction %s misses landmark %s occurrence %d observed in its range", ErrCorrupt, cr.ID, key.id, key.num)
834					}
835				}
836				for key := range got {
837					if _, ok := want[key]; !ok {
838						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d with no observation in its range", ErrCorrupt, cr.ID, key.id, key.num)
839					}
840				}
