842				// 观测次数核对：回环校正只移动轨迹、不增删已接受观测，因此对
843				// 于依据完整的记录，其每个受影响路标出现的校正前、校正后次数
844				// 都必须等于截至“本记录结束时间”已经接纳、归属该次出现的观
845				// 测总数。这个总数按各记录自己的结束帧从累计快照截取：包含锚
846				// 点之前属于同一次出现的观测与结束帧上的观测，不只是被移动的
847				// [anchor,end] 那段；同帧多条观测各计一次，无观测帧不增加；
848				// 该出现保存的固定旧观测贡献（旧地图既有观测）也要计入，不能
849				// 当作零。结束帧之后才接纳的观测（例如记录结束于 300、后来在
850				// 400 又观测一次）不属于本记录；后来对重叠范围的再次校正不改
851				// 变判断——每条记录都以自己的结束时间为准。各次出现分别核
852				// 对，不能借另一出现的观测补足；已失效的旧出现只要被该条校正
853				// 涉及同样核对。校正前或校正后任一次数不符，即使路标列表、位
854				// 置与文件校验都正常，也按损坏拒绝整份地图。省略出现编号的旧
855				// 条目沿用按第 1 次出现解释的规则。范围内含 null 旧帧时依据不
856				// 完整，保留旧文件的既有打开规则（fullyBased 为假，不到此）。
857				// 截至本记录结束帧的累计计数快照与固定旧贡献都来自唯一一次共享
858				// 扫描（tally，见 tally.go），与路标总次数核对共用同一套归属与
859				// 计数规则。
860				snapshot := tally.cumBySrc[endIdx-1]
861				for _, lc := range cr.Landmarks {
862					num := lc.Occurrence
863					if num == 0 {
864						num = 1
865					}
866					wantCount := snapshot[occurrenceKey{id: lc.ID, num: num}] + legacyByKey[occurrenceKey{id: lc.ID, num: num}]
867					if lc.Before.Count != wantCount {
868						return fmt.Errorf("%w: correction %s landmark %s occurrence %d records %d pre-correction observations but %d were accepted by its end time %d", ErrCorrupt, cr.ID, lc.ID, num, lc.Before.Count, wantCount, cr.EndTime)
869					}
870					if lc.After.Count != wantCount {
871						return fmt.Errorf("%w: correction %s landmark %s occurrence %d records %d post-correction observations but %d were accepted by its end time %d", ErrCorrupt, cr.ID, lc.ID, num, lc.After.Count, wantCount, cr.EndTime)
872					}
873				}
874			}
875			if _, dup := corrIDs[cr.ID]; dup {
876				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
877			}
878			corrIDs[cr.ID] = struct{}{}
879		}
880		// 相邻校正衔接核对：同一帧再次被校正时，本次记录的校正前值必须承接
881		// 此前最后一次覆盖该帧的记录的校正后值——上面的几何核对只确认每条
882		// 记录自身的前后值描述同一次刚体重定位，不确认两次校正之间的承接关
883		// 系；没有这项核对，即使校验和正确、每条记录各自合法，两条记录仍可
884		// 对同一帧给出互相矛盾的历史。按提交次序逐帧维护“最后一次覆盖该帧
885		// 的记录”：中间提交但未覆盖该帧的校正不改变它的上次结果；两次校正
886		// 只部分重叠时只对共同涉及的帧检查；没有前次覆盖的帧（如先校正
887		// 100~300、追加 400、再校正 200~400 时的 400）不要求衔接。位置用
888		// coordClose、朝向用 angleClose（均为 1e-9 相对/绝对容差，处理 ±π
889		// 跨边界），方差必须完全一致；衔接不符即按损坏拒绝整份文件，即使当
890		// 前轨迹与最后一次校正一致、或这些帧没有路标观测，也不能放过。兼容
891		// 规则与最后一次校正核对相同：前后两次校正任一范围内含缺少逐帧依据
892		// 的 null 旧帧时跳过该处比较，但不越过这次记录改用更早结果——上次
893		// 结果仍以最后一次覆盖记录为准；同一文件内其他依据完整的衔接仍须检
894		// 查。校正记录保持提交时的快照与次序，不为消除矛盾而改写。
895		prevByFrame := make([]int, len(fd.Trajectory))
896		for j := range prevByFrame {
897			prevByFrame[j] = -1
898		}
899		for i := range fd.Corrections {
900			r := corrRanges[i]
901			cr := fd.Corrections[i]
902			for j := r.anchorIdx; j <= r.endIdx; j++ {
903				p := prevByFrame[j]
904				if p >= 0 && r.fullyBased && corrRanges[p].fullyBased {
905					prev := fd.Corrections[p]
906					want := prev.Poses[j-corrRanges[p].anchorIdx].After
907					got := cr.Poses[j-r.anchorIdx].Before
908					t := fd.Trajectory[j].Time
909					if !coordClose(got.X, want.X) {
910						return fmt.Errorf("%w: correction %s records pre-correction x %v at frame time %d but the previous correction %s covering that frame recorded corrected x %v", ErrCorrupt, cr.ID, got.X, t, prev.ID, want.X)
911					}
912					if !coordClose(got.Y, want.Y) {
913						return fmt.Errorf("%w: correction %s records pre-correction y %v at frame time %d but the previous correction %s covering that frame recorded corrected y %v", ErrCorrupt, cr.ID, got.Y, t, prev.ID, want.Y)
914					}
915					if !angleClose(got.Heading, want.Heading) {
916						return fmt.Errorf("%w: correction %s records pre-correction heading %v at frame time %d but the previous correction %s covering that frame recorded corrected heading %v", ErrCorrupt, cr.ID, got.Heading, t, prev.ID, want.Heading)
917					}
918					if got.Variance != want.Variance {
919						return fmt.Errorf("%w: correction %s records pre-correction variance %v at frame time %d but the previous correction %s covering that frame recorded corrected variance %v", ErrCorrupt, cr.ID, got.Variance, t, prev.ID, want.Variance)
920					}
921				}
922				// 不论是否比较，本记录都成为该帧新的最后一次覆盖记录。
923				prevByFrame[j] = i
924			}
925		}
