932		// 后来追加的 500 帧不属于任一条，旧记录也不因后续校正而被改写）。
933		// 对每个已导入帧 j（trajectory[0] 是初始位姿，不是可校正的帧），先
934		// 按提交次序求最后一条覆盖它的记录（不论依据是否完整）：若该记录
935		// 范围内逐帧依据完整，就把其该帧的校正后值作为期望，逐帧核对保存
936		// 的位置、朝向与位置方差，锚点与结束帧同样在内；范围内没有任何路
937		// 标观测的帧也必须符合（直接逐帧比对，不借路标位置核对间接发现矛
938		// 盾）。兼容规则：最后一条覆盖记录范围内含缺少逐帧依据的 null 旧
939		// 帧时跳过该帧的比较，而不是回退到更早的完整依据记录要求当前位姿
940		// 回到旧结果；其前后帧若最后覆盖记录不同且该记录依据完整，仍须核
941		// 对；没有任何覆盖记录的帧不核对，纯旧文件因此全部自然跳过。位置
942		// 用 coordClose、朝向用 angleClose（均为 1e-9 相对/绝对容差，处理
943		// ±π 跨边界），方差必须完全一致；合并距离只是导入/校正时的观测接
944		// 纳门槛，不能用来放宽这些要求。
945		lastByFrame := make([]int, len(fd.Trajectory))
946		for j := range lastByFrame {
947			lastByFrame[j] = -1
948		}
949		for i := range fd.Corrections {
950			r := corrRanges[i]
951			for j := r.anchorIdx; j <= r.endIdx; j++ {
952				lastByFrame[j] = i
953			}
954		}
955		for j := 1; j < len(fd.Trajectory); j++ {
956			i := lastByFrame[j]
957			if i < 0 || !corrRanges[i].fullyBased {
958				// 没有任何覆盖记录，或最后一条覆盖该帧的记录范围内含缺少
959				// 逐帧依据的 null 旧帧：按兼容规则跳过，不改用更早记录。
960				continue
961			}
962			cr := fd.Corrections[i]
963			r := corrRanges[i]
964			want := cr.Poses[j-r.anchorIdx].After
965			got := fd.Trajectory[j]
966			if !finitePose(got) {
967				return fmt.Errorf("%w: frame at time %d contradicts its last correction %s: saved pose is non-finite", ErrCorrupt, got.Time, cr.ID)
968			}
969			if !coordClose(got.X, want.X) {
970				return fmt.Errorf("%w: correction %s is the last correction covering frame time %d but saved x %v does not match its corrected x %v", ErrCorrupt, cr.ID, got.Time, got.X, want.X)
971			}
972			if !coordClose(got.Y, want.Y) {
973				return fmt.Errorf("%w: correction %s is the last correction covering frame time %d but saved y %v does not match its corrected y %v", ErrCorrupt, cr.ID, got.Time, got.Y, want.Y)
974			}
975			if !angleClose(got.Heading, want.Heading) {
976				return fmt.Errorf("%w: correction %s is the last correction covering frame time %d but saved heading %v does not match its corrected heading %v", ErrCorrupt, cr.ID, got.Time, got.Heading, want.Heading)
977			}
978			if got.Variance != want.Variance {
979				return fmt.Errorf("%w: correction %s is the last correction covering frame time %d but saved variance %v does not match its corrected variance %v", ErrCorrupt, cr.ID, got.Time, got.Variance, want.Variance)
980			}
981		}
982		// 段首次导入结果核对：重复导入原段时直接返回保存的首次结果，因此保存
