1113				if lm == nil {
1114					return fmt.Errorf("%w: invalidation %s result points to unknown landmark %s", ErrCorrupt, iv.ID, l.ID)
1115				}
1116				if len(lm.Occurrences) == 0 {
1117					return fmt.Errorf("%w: invalidation %s result points to flat legacy landmark %s which has no invalidated occurrence", ErrCorrupt, iv.ID, l.ID)
1118				}
1119				if l.Occurrence > len(lm.Occurrences) {
1120					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which does not exist", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
1121				}
1122				// 出现编号连续性已在上方路标校验中强制，该下标处编号即 l.Occurrence。
1123				oj := lm.Occurrences[l.Occurrence-1]
1124				if oj.Active {
1125					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which is still active", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
1126				}
1127				if oj.InvalidOpID != iv.ID || oj.InvalidTime != iv.Time || oj.InvalidReason != iv.Reason {
1128					return fmt.Errorf("%w: invalidation %s result for landmark %s occurrence %d does not match its saved invalidation (op %q, time %d, reason %q)", ErrCorrupt, iv.ID, l.ID, l.Occurrence, oj.InvalidOpID, oj.InvalidTime, oj.InvalidReason)
1129				}
1130				invalTriples[invalTriple{op: iv.ID, lm: l.ID, num: l.Occurrence}] = struct{}{}
1131			}
1132		}
1133		// 反向核对：每个已失效出现都必须能在失效操作序列中找到引用同一（操作，
1134		// 路标，出现编号）三元组的条目。正向核对已保证被引用出现的失效时间与
1135		// 原因和引用方一致；此处堵住另一方向的矛盾：出现凭空携带失效信息、
1136		// 声称撤下它的操作记录实际指向另一次出现，或两次出现声称被同一操作
1137		// 撤下（一次操作对同一路标只会撤下当时唯一的有效出现）。旧地图没有
1138		// 失效操作时，平铺路标视为有效、不携带失效信息，不会触发；旧地图后来
1139		// 产生的失效操作同样在上述核对之列，不要求补齐原本缺失的逐帧观测。
1140		for _, lm := range fd.Landmarks {
1141			for _, oj := range lm.Occurrences {
1142				if oj.Active {
1143					continue
1144				}
1145				if _, ok := invalTriples[invalTriple{op: oj.InvalidOpID, lm: lm.ID, num: oj.Number}]; !ok {
1146					return fmt.Errorf("%w: landmark %s occurrence %d is marked invalidated by operation %q which does not record that invalidation", ErrCorrupt, lm.ID, oj.Number, oj.InvalidOpID)
1147				}
1148			}
1149		}
1150		return nil
1151	}
1152	
1153	func finitePose(p Pose) bool {
1154		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
1155	}
1156	
1157	// geomTol 是打开时核对校正记录几何一致性的相对容差（另含 1 的绝对项）。
1158	const geomTol = 1e-9
1159	
1160	// coordClose 判断保存坐标 got 是否在容许误差内等于期望 want：误差不得
1161	// 超过 geomTol 乘以 1、|want|、|got| 三者中的最大值。参与比较的值都已
1162	// 校验为有限，差值必有限，NaN 不会混入并被误当相等。
1163	func coordClose(got, want float64) bool {
1164		scale := math.Max(1, math.Max(math.Abs(want), math.Abs(got)))
1165		return math.Abs(got-want) <= geomTol*scale
1166	}
1167	
1168	// angleClose 按最短角度差判断两个角度是否相等，容差 geomTol 弧度。两个
1169	// 角度都已校验为有限；差值经归一化到 [-π,π) 即最短角度差，正确处理
1170	// ±π 附近跨边界但物理方向相同的情形。
1171	func angleClose(got, want float64) bool {
1172		return math.Abs(normalizeAngle(got-want)) <= geomTol
1173	}
1174	
1175	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
1176	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
1177	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
1178		h := sha256.New()
1179		var b [8]byte
1180		binary.BigEndian.PutUint64(b[:], uint64(anchor))
1181		h.Write(b[:])
1182		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
1183			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
1184			h.Write(b[:])
1185		}
1186		return fmt.Sprintf("%x", h.Sum(nil))
1187	}
1188	
1189	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
1190	func (m *Map) saveExclusive() error {
1191		data, err := encodeFile(m.state)
1192		if err != nil {
1193			return err
1194		}
1195		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
1196		if err != nil {
1197			return err
1198		}
1199		return writeAndClose(f, data, m.path)
1200	}
1201	
1202	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
1203	func (m *Map) saveReplace() (err error) {
1204		data, err := encodeFile(m.state)
1205		if err != nil {
1206			return err
1207		}
1208		dir, base := filepath.Split(m.path)
1209		if dir == "" {
1210			dir = "."
1211		}
1212		f, err := os.CreateTemp(dir, base+".tmp-*")
1213		if err != nil {
1214			return err
1215		}
1216		tmpName := f.Name()
1217		// 任何失败路径都尽力清理临时文件。
1218		defer func() {
1219			if err != nil {
1220				_ = os.Remove(tmpName)
1221			}
1222		}()
1223		if err = writeAndClose(f, data, tmpName); err != nil {
1224			return err
1225		}
1226		if err = os.Rename(tmpName, m.path); err != nil {
1227			return err
1228		}
1229		return nil
1230	}
1231	
1232	func writeAndClose(f *os.File, data []byte, name string) (err error) {
1233		defer func() {
1234			if cerr := f.Close(); err == nil {
1235				err = cerr
1236			}
1237		}()
1238		if _, err = f.Write(data); err != nil {
1239			return err
1240		}
1241		if err = f.Sync(); err != nil {
1242			return err
1243		}
1244		return nil
1245	}
1246	
1247	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
1248	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
1249	func canonicalHash(frames []Frame) string {
1250		h := sha256.New()
1251		var lenBuf [4]byte
1252		var numBuf [8]byte
1253		putU32 := func(v uint32) {
1254			binary.BigEndian.PutUint32(lenBuf[:], v)
1255			h.Write(lenBuf[:])
1256		}
1257		putU64 := func(v uint64) {
1258			binary.BigEndian.PutUint64(numBuf[:], v)
1259			h.Write(numBuf[:])
1260		}
1261		putStr := func(s string) {
1262			putU32(uint32(len(s)))
1263			h.Write([]byte(s))
1264		}
1265	
1266		putU32(uint32(len(frames)))
1267		for _, fr := range frames {
1268			putU64(uint64(fr.Time))
1269			putU64(math.Float64bits(fr.DX))
1270			putU64(math.Float64bits(fr.DY))
1271			putU64(math.Float64bits(fr.DHeading))
1272			putU64(math.Float64bits(fr.MoveVariance))
1273			putU32(uint32(len(fr.Observations)))
1274			for _, ob := range fr.Observations {
1275				putStr(ob.ID)
1276				putU64(math.Float64bits(ob.X))
1277				putU64(math.Float64bits(ob.Y))
1278			}
1279		}
1280		return fmt.Sprintf("%x", h.Sum(nil))
1281	}
1282

