		}
		cur, _ := m.CurrentPose()
		if cur.Time != 0 {
			t.Fatalf("current time = %d, pose leaked", cur.Time)
		}
	})

	t.Run("merge with committed active overflow", func(t *testing.T) {
		m := newMap(t, hugeCfg)
