import (
	"bytes"
	"encoding/binary"
	"errors"
	"hash/crc32"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// splicePayload 对文件 JSON 载荷做原样字节替换（Go encoding/json 不能编码
// NaN/Inf，用 1e1000 这类越界字面量注入非有限值），再按文件格式重组并重算
// CRC。occ 为 0 起的匹配序号。
func splicePayload(t *testing.T, path string, old, neu []byte, occ int) {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	payload := raw[headerLen : len(raw)-4]
	idx := -1
	for k := 0; k <= occ; k++ {
		next := bytes.Index(payload[idx+1:], old)
		if next < 0 {
			t.Fatalf("marker %s occurrence %d not found", old, occ)
		}
		idx += next + 1
